renderer.fragment:
void main(){
  float asp = iResolution.x / max(iResolution.y, 1.0);
  vec2 p = vec2((uv.x - 0.5) * asp, uv.y);
  float h = u_horizon;
  // floor weight with a soft curved cove into the wall
  float fl = 1.0 - smoothstep(h - u_cove, h + u_cove, uv.y);
  // key light pool centred above the cove, falling onto wall and floor
  vec2 lc = vec2(0.0, h + 0.18);
  vec2 ld = (p - lc) * vec2(0.55, mix(1.0, 1.6, fl));
  float s = max(u_lightSpread, 0.05);
  float light = exp(-dot(ld, ld) * 2.4 / (s * s));
  vec3 col = u_bgColor * mix(0.42, 1.0, clamp(light * u_lightIntensity, 0.0, 1.0));
  col += u_lightColor * light * u_lightIntensity * 0.22;
  col *= mix(vec3(1.0), u_lightColor, 0.25 * clamp(u_lightIntensity, 0.0, 1.0));
  // gentle cove occlusion and floor falloff toward camera
  float coveBand = exp(-pow((uv.y - h) / max(u_cove, 0.01), 2.0) * 1.5);
  col *= 1.0 - 0.06 * coveBand;
  col *= mix(1.0, 0.82, fl * clamp(1.0 - uv.y / max(h, 0.01), 0.0, 1.0));
  // optional perspective floor grid
  if (u_grid > 0.5) {
    float dy = max(h - uv.y, 1e-3);
    float z = 0.25 / dy;
    vec2 w = vec2(p.x * z, z) * u_gridScale;
    vec2 fw = max(fwidth(w), vec2(1e-4));
    vec2 g = abs(fract(w - 0.5) - 0.5) / fw;
    float line = 1.0 - clamp(min(g.x, g.y), 0.0, 1.0);
    float fade = clamp(dy / max(h, 0.01) * 3.0, 0.0, 1.0) * fl;
    fade *= clamp(1.0 - max(fw.x, fw.y) * 1.5, 0.0, 1.0);
    col *= 1.0 - line * u_gridOpacity * 0.55 * fade;
  }
  // soft contact shadow pool on the floor
  vec2 sc = vec2(0.0, h * 0.55);
  float ss = max(u_shadowSize, 0.01);
  vec2 sd = (p - sc) / vec2(ss, ss * 0.22);
  float sh = exp(-dot(sd, sd) * 1.8) * u_shadowStrength * fl;
  col *= 1.0 - sh * 0.7;
  // subtle vignette + dither against banding
  vec2 vq = (uv - 0.5) * vec2(asp, 1.0);
  col *= 1.0 - 0.28 * dot(vq, vq);
  col += (hash(uv * iResolution) - 0.5) / 255.0;
  fragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}
